import { loadVariableFont } from "@remotion/google-fonts/InterTight";
import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, continueRender, delayRender, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The text fading in as a draft, then each glyph sharpening into its final
// weight in turn. Frames on the 30 fps scene timeline, after `delay` and
// `speed`. The ids are public: a saved `timing` prop refers to them.

type EnhanceCountElementId = "enter" | `glyph:${number}`;

interface EnhanceCountTimingProps {
  text?: string;
  span?: number;
}

const DEFAULT_TEXT = "Draft it fast.\nFinish it sharp.";
const ENHANCE_SPAN = 34;
/** The draft fades in over `ENTER_LEN`. */
const ENTER_LEN = 14;
/** Glyphs start sharpening at `ENHANCE_AT`, at most `ENHANCE_MAX_GAP` apart. */
const ENHANCE_AT = 38;
const ENHANCE_MAX_GAP = 2.4;

/** The lines drawn: trimmed, blank ones dropped, a fallback when none is left. */
function linesOf(text: string) {
  const l = text
    .split("\n")
    .map((s) => s.trim())
    .filter(Boolean);
  return l.length ? l : ["Finish it sharp."];
}

// `glyph:<i>` counts every character across the lines, spaces included. A
// glyph's sharpening is a spring that keeps settling after its length, the
// time until the next glyph starts.
const enhanceCountTimeline = defineTimeline<
  EnhanceCountElementId,
  EnhanceCountTimingProps
>(({ text = DEFAULT_TEXT, span = ENHANCE_SPAN }) => {
  const chars = linesOf(text).flatMap((line) => Array.from(line));
  const gap = Math.min(ENHANCE_MAX_GAP, span / Math.max(1, chars.length));
  const elements: TimelineElement<EnhanceCountElementId>[] = [
    {
      id: "enter",
      lane: "Text",
      label: "Draft in",
      start: 0,
      length: ENTER_LEN,
    },
  ];
  chars.forEach((ch, i) => {
    elements.push({
      id: `glyph:${i}`,
      lane: "Glyphs",
      label: ch,
      start: ENHANCE_AT + i * gap,
      length: gap,
      follows: i > 0 ? `glyph:${i - 1}` : undefined,
    });
  });
  return elements;
});

const inter = loadVariableFont("normal", { subsets: ["latin"] });

interface EnhanceCountProps {
  text?: string;
  highlight?: string;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy; a variable font keeps the weight sweep smooth. Inter Tight by default. */
  fontFamily?: string;
  /** Weight the glyphs settle on. */
  fontWeight?: number;
  /** Weight the glyphs start from, before they sharpen. */
  draftWeight?: number;
  /** Frames the sharpening sweeps across the whole text. */
  span?: number;
  /** Size of the text block, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the draft fading in and single glyphs
   * sharpening, by the ids in `./timeline`. Frames on the scene timeline,
   * after `delay` and `speed`.
   */
  timing?: Timing<EnhanceCountElementId>;
}

const THEMES = {
  dark: {
    bg: "#1C1C1E",
    ink: "#E9E9E6",
    accent: "#6D5BFF",
  },
  light: {
    bg: "#E9E9E6",
    ink: "#0B0B0C",
    accent: "#6D5BFF",
  },
} as const;

const DRAFT_WGHT = 100;
const DONE_WGHT = 440;
const TRACK = -0.025;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface LineMetrics {
  chars: string[];
  x: number[];
  width: number;
}

interface Metrics {
  lines: LineMetrics[];
  capTop: number;
  baseline: number;
}

function measure(lines: string[], font: string): Metrics {
  const canvas = document.createElement("canvas");
  canvas.width = 10;
  canvas.height = 10;
  const ctx = canvas.getContext("2d");
  const size = 200;
  const out: LineMetrics[] = [];
  let capTop = 0.72;
  let baseline = 0.8;
  if (!ctx) {
    for (const l of lines) {
      const chars = Array.from(l);
      out.push({
        chars,
        x: chars.map((_, i) => i * 0.55),
        width: chars.length * 0.55,
      });
    }
    return { lines: out, capTop, baseline };
  }
  ctx.font = font;
  ctx.letterSpacing = `${TRACK * size}px`;
  for (const l of lines) {
    const chars = Array.from(l);
    const x: number[] = [];
    let acc = "";
    for (const ch of chars) {
      x.push(ctx.measureText(acc).width / size);
      acc += ch;
    }
    out.push({ chars, x, width: ctx.measureText(acc).width / size });
  }
  const fm = ctx.measureText("H");
  const asc = fm.fontBoundingBoxAscent / size;
  const desc = fm.fontBoundingBoxDescent / size;
  baseline = (1 - (asc + desc)) / 2 + asc;
  capTop = fm.actualBoundingBoxAscent / size;
  return { lines: out, capTop, baseline };
}

function useMetrics(
  lines: string[],
  fontFamily: string,
  fontWeight: number,
  draftWeight: number,
) {
  const font = `${fontWeight} 200px "${fontFamily}"`;
  const key = `${font}\u0002${draftWeight}\u0002${lines.join("\n")}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("enhance-count: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      inter.waitUntilDone(),
      document.fonts.load(`${fontWeight} 100px "${fontFamily}"`),
      document.fonts.load(`${draftWeight} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({ key, m: measure(key.split("\u0002")[2].split("\n"), font) });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, font, fontFamily, fontWeight, draftWeight]);
  return state && state.key === key ? state.m : null;
}

const mix = (a: string, b: string, u: number) =>
  `color-mix(in oklab, ${a} ${((1 - u) * 100).toFixed(1)}%, ${b})`;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function EnhanceCountBase(props: EnhanceCountProps) {
  const {
    text = DEFAULT_TEXT,
    highlight = "sharp.",
    accent,
    ink,
    background,
    fontFamily = inter.fontFamily,
    fontWeight = DONE_WGHT,
    draftWeight = DRAFT_WGHT,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    enhanceCountTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const spot = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const lines = useMemo(() => linesOf(text), [text]);
  const m = useMetrics(lines, fontFamily, fontWeight, draftWeight);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const widest = Math.max(0.1, ...m.lines.map((l) => l.width));
  const LH = 1.1;
  const F = Math.min(
    (W * (portrait ? 0.78 : 0.56)) / widest,
    (H * (portrait ? 0.07 : 0.12)) / m.capTop,
  );
  const lineH = F * LH;
  const blockH = lineH * m.lines.length;
  const top0 = (H - blockH) / 2;

  const hiWords = new Set(
    highlight
      .split(/\s+/)
      .filter(Boolean)
      .map((w) => w.toLowerCase()),
  );
  const enterEl = tl.get("enter");
  const enter = interpolate(t, [enterEl.start, enterEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  let gi = 0;
  const glyphs = m.lines.flatMap((line, li) => {
    const left0 = (W - line.width * F) / 2;
    const baseY = top0 + li * lineH + (lineH + m.capTop * F) / 2;
    const words: boolean[] = [];
    let wordStart = 0;
    for (let i = 0; i <= line.chars.length; i++) {
      if (i === line.chars.length || line.chars[i] === " ") {
        const w = line.chars.slice(wordStart, i).join("").toLowerCase();
        for (let k = wordStart; k < i; k++) words[k] = hiWords.has(w);
        words[i] = false;
        wordStart = i + 1;
      }
    }
    return line.chars.map((ch, i) => {
      const idx = gi++;
      const u = spring({
        frame: t - tl.get(`glyph:${idx}`).start,
        fps,
        config: { damping: 18, stiffness: 140, mass: 0.8 },
      });
      const uc = Math.min(1, Math.max(0, u));
      const next = i + 1 < line.chars.length ? line.x[i + 1] : line.width;
      const slot = (next - line.x[i]) * F;
      const wght = draftWeight + (fontWeight - draftWeight) * u;
      const blur = (1 - uc) * F * 0.045;
      const hi = words[i] && ch !== " ";
      const color = hi ? mix(fg, spot, uc) : fg;
      return (
        <div
          key={`${li}-${i}`}
          style={{
            position: "absolute",
            left: left0 + line.x[i] * F,
            width: slot,
            top: baseY - m.baseline * F,
            height: F,
            lineHeight: `${F}px`,
            textAlign: "center",
            whiteSpace: "pre",
            fontFamily,
            fontSize: F,
            fontVariationSettings: `"wght" ${wght.toFixed(1)}`,
            color,
            opacity: enter * (0.5 + 0.5 * uc),
            filter: blur > 0.05 ? `blur(${blur.toFixed(2)}px)` : undefined,
          }}
        >
          {ch}
        </div>
      );
    });
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>{glyphs}</ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  text: {
    type: "text-content",
    default: "Draft it fast.\nFinish it sharp.",
    description: "Text",
  },
  highlight: {
    type: "text-content",
    default: "sharp.",
    description: "Highlight",
  },
  fontWeight: {
    type: "number",
    default: 440,
    min: 100,
    max: 900,
    step: 10,
    description: "Final weight",
    hiddenFromList: false,
  },
  draftWeight: {
    type: "number",
    default: 100,
    min: 100,
    max: 900,
    step: 10,
    description: "Draft weight",
    hiddenFromList: false,
  },
  span: {
    type: "number",
    default: 34,
    min: 0,
    max: 90,
    step: 1,
    description: "Sweep (frames)",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: undefined,
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Inter Tight",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","text","highlight","fontWeight","draftWeight","span","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  text: "Draft it fast.\nFinish it sharp.",
  highlight: "sharp.",
  fontWeight: 440,
  draftWeight: 100,
  span: 34,
  fontFamily: "Inter Tight",
  scale: 1,
  delay: 0,
  speed: 1,
};

type EnhanceCountElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof EnhanceCountBase>;

const EnhanceCountInner = forwardRef<
  HTMLDivElement,
  EnhanceCountElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<EnhanceCount>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <EnhanceCountBase
          {...(componentProps as unknown as ComponentProps<typeof EnhanceCountBase>)}
        />
      </div>
    </Sequence>
  );
});

export const EnhanceCount = Interactive.withSchema({
  Component: EnhanceCountInner,
  componentName: "<EnhanceCount>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
